  ('60dd8965-35a6-5ed0-b839-c91c357c7673', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А та проблема зі спиною?", "Який зуб вас болить?", "А якщо немає світла?"]'::jsonb, 2, null, '{}'::text[], 'A ako nema struje?', null, null, 'Прозвучало: «A ako nema struje?» — «А якщо немає світла?».', (select id from public.lessons where id = '692e9310-7a5b-5adf-9f0a-a66b72fc5459'), 'PUBLISHED', 'claude_assessment_v5'),
  ('44ddf98f-d08b-5bfb-b000-a61c511096a7', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ні, бо вам потрібно три дні постільного режиму.", "Ось тут, праворуч, під ребрами.", "У мене ще й проблеми з травленням."]'::jsonb, 1, null, '{}'::text[], 'Ovdje s desne strane, ispod rebara.', null, null, 'Прозвучало: «Ovdje s desne strane, ispod rebara.» — «Ось тут, праворуч, під ребрами.».', (select id from public.lessons where id = 'b6859b5e-db71-543a-8d05-db9b43811d8a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b6cc027a-d169-5a29-82ce-d2ac405ab9dc', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ці пастилки добрі. Беріть одну кожні три години.", "Добрий день, мені щось від горла, без рецепта.", "Курю, але менше, ніж раніше."]'::jsonb, 1, null, '{}'::text[], 'Dobar dan, trebam nešto za grlo, bez recepta.', null, null, 'Прозвучало: «Dobar dan, trebam nešto za grlo, bez recepta.» — «Добрий день, мені щось від горла, без рецепта.».', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a9165d70-ec7e-5f01-8ef7-a0389cf98ebd', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Що потрібно, коли Софія повернеться?', 'Dijete je bolesno', '["Новий одяг", "Оплата", "Довідка від педіатра"]'::jsonb, 2, null, '{}'::text[], null, 'Olena: Dobro jutro, Sofija danas ne dolazi u vrtić. Ima temperaturu i kašlje.
