  ('f7c9cffd-2020-5c29-b016-e79602e25a52', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Покажи мені новий малюнок після шахів.", "Правда, вона танцює щосереди.", "Шкода! Начальник хоче відсвяткувати вдалий рік."]'::jsonb, 0, null, '{}'::text[], 'Pokaži mi novi crtež poslije šaha.', null, null, 'Прозвучало: «Pokaži mi novi crtež poslije šaha.» — «Покажи мені новий малюнок після шахів.».', (select id from public.lessons where id = '1c16ceee-5f42-536a-98b4-7dcabaa3be6d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('05c0491f-f0e1-5850-9559-6626daf5cc1a', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Гандбол або баскетбол, тут вони дуже популярні.", "На жаль, я не можу прийти, у мене немає часу.", "Не хвилюйся, нам вистачить до кінця місяця."]'::jsonb, 1, null, '{}'::text[], 'Nažalost, ne mogu doći, nemam vremena.', null, null, 'Прозвучало: «Nažalost, ne mogu doći, nemam vremena.» — «На жаль, я не можу прийти, у мене немає часу.».', (select id from public.lessons where id = '3ed8282d-b9fa-5151-b184-73fd352f8ba7'), 'PUBLISHED', 'claude_assessment_v5'),
  ('fc079d9f-353e-5396-8060-4ddccdfb34e7', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Я всюди дивилася!", "Нічого не сказав, тільки що передзвонить.", "Знаю, але я хвилююся через гроші."]'::jsonb, 0, null, '{}'::text[], 'Svugdje sam gledala!', null, null, 'Прозвучало: «Svugdje sam gledala!» — «Я всюди дивилася!».', (select id from public.lessons where id = '3f440ad8-f057-5898-b773-6aa8816fa8a3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('cd3a4968-1faa-5d48-88ad-5e886ac3e9af', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Що буде, якщо йде дощ?', 'Koncert u parku', '["Концерт у театрі", "Концерт у неділю", "Концерт скасують"]'::jsonb, 0, null, '{}'::text[], null, 'KONCERT U PARKU ZRINJEVAC
