  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('7a414dc1-db08-5b3f-bcda-7bf9c1acf061', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Чудово! Ми слухали Морський орган на набережній.", "Тоді поїдемо на прогулянку в суботу зранку.", "Я складу план подорожі сьогодні ввечері."]'::jsonb, 0, null, '{}'::text[], 'Predivno! Slušali smo morske orgulje na rivi.', null, null, 'Прозвучало: «Predivno! Slušali smo morske orgulje na rivi.» — «Чудово! Ми слухали Морський орган на набережній.».', (select id from public.lessons where id = '9a44edc5-7e46-5377-bfcb-20cd93ac333b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b8f177d5-3c94-508f-bb01-ed76db9112c5', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Можу, але дуже боляче.", "Ми гуляли набережною до римського форуму.", "Зранку проясниться, але по обіді можливі зливи."]'::jsonb, 2, null, '{}'::text[], 'Ujutro će se razvedriti, ali popodne su mogući pljuskovi.', null, null, 'Прозвучало: «Ujutro će se razvedriti, ali popodne su mogući pljuskovi.» — «Зранку проясниться, але по обіді можливі зливи.».', (select id from public.lessons where id = '0cb42e87-0ece-5e12-a07c-05cb5c370157'), 'PUBLISHED', 'claude_assessment_v5'),
  ('fde5a3c3-3e47-506c-aba5-c006fbbf7555', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Тату, тут живуть ведмеді?", "Де ви були вчора ввечері?", "Даріє, ти була в природному парку Велебіт?"]'::jsonb, 2, null, '{}'::text[], 'Darja, jesi li bila u parku prirode Velebit?', null, null, 'Прозвучало: «Darja, jesi li bila u parku prirode Velebit?» — «Даріє, ти була в природному парку Велебіт?».', (select id from public.lessons where id = '84a20a00-701a-5ce5-a3c8-fca72986f912'), 'PUBLISHED', 'claude_assessment_v5'),
  ('df9744ef-5fd4-5f9d-8b41-9bcc74e94024', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Як вони повертаються?', 'Razglednica s otoka', '["Літаком", "Поромом", "Автобусом"]'::jsonb, 1, null, '{}'::text[], null, 'Draga Marija,
pozdrav s Hvara! More je toplo i čisto, a plaže su prekrasne. Svaki dan se kupamo i jedemo svježu ribu. Navečer šetamo uz rivu. Grad je mali, ali ima puno ljudi. Vraćamo se u nedjelju trajektom. Jedva čekam da se vidimo!
Grli te Oksana', 'Дорога Маріє,
привіт із Хвару! Море тепле й чисте, а пляжі чудові. Щодня ми купаємося і їмо свіжу рибу. Увечері гуляємо набережною. Місто маленьке, але людей багато. Повертаємося в неділю поромом. Не можу дочекатися нашої зустрічі!
Обіймаю, Оксана', 'Текст «Листівка з острова». Правильна відповідь: «Поромом».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('a1ee71cc-45b9-5a73-8245-26363f0675d0', v_aid, 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li bilo glazbe?', '["Da, pjevala je klapa. A u kafiću smo probali maraskino.", "Zdravstvenu iskaznicu i popis lijekova.", "Šest eura, a juha je besplatna."]'::jsonb, 0, null, '{}'::text[], 'Je li bilo glazbe?', null, null, 'Діалог «Далматинський вечір»: «Je li bilo glazbe?» (Була музика?) — «Da, pjevala je klapa. A u kafiću smo probali maraskino.» (Так, співала клапа. А в кафе ми скуштували мараскіно.).', (select id from public.lessons where id = '9a44edc5-7e46-5377-bfcb-20cd93ac333b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bbcf2f5e-f59e-518a-912d-86f216899486', v_aid, 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoćemo li kampirati ili uzeti privatni smještaj?', '["U kutiji, na dnu. I vijci su u maloj vrećici.", "Djeca žele kamp i šator!", "Mjesto sastanka je na tramvajskoj stanici Mihaljevac."]'::jsonb, 1, null, '{}'::text[], 'Hoćemo li kampirati ili uzeti privatni smještaj?', null, null, 'Діалог «Куди поїдемо?»: «Hoćemo li kampirati ili uzeti privatni smještaj?» (Будемо жити в наметі чи візьмемо приватне житло?) — «Djeca žele kamp i šator!» (Діти хочуть кемпінг і намет!).', (select id from public.lessons where id = '373074e1-3c4b-5d0f-a4f3-3ed06e0904f2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f2baba1d-c654-5c6f-afe0-eefecf97bc00', v_aid, 7, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dašo, kamo ćemo ići na godišnji ove godine?', '["Rade. Provjerite i zvonce prije vožnje.", "Mislim da ćemo putovati u Dalmaciju, u predsezoni.", "Ultrazvuk srca i kontrolu za tri mjeseca."]'::jsonb, 1, null, '{}'::text[], 'Dašo, kamo ćemo ići na godišnji ove godine?', null, null, 'Діалог «Куди поїдемо?»: «Dašo, kamo ćemo ići na godišnji ove godine?» (Дашо, куди поїдемо у відпустку цього року?) — «Mislim da ćemo putovati u Dalmaciju, u predsezoni.» (Думаю, поїдемо в Далмацію, на початку сезону.).', (select id from public.lessons where id = '373074e1-3c4b-5d0f-a4f3-3ed06e0904f2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9fd3ae42-c25d-5795-9c26-99931bbc42ba', v_aid, 8, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Zašto ljudi u Zagorju drugačije govore?', '["Для мене приморський, Далмація — один із найгарніших регіонів.", "Ліка — континентальна, зими там найхолодніші.", "Це кайкавське наріччя. У Далмації звучить знову інакше."]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Zašto ljudi u Zagorju drugačije govore?
Marko: To je kajkavsko narječje. U Dalmaciji zvuči opet drugačije.
Darja: A Lika?
Marko: Lika je kontinentalna, zime su najhladnije.
Darja: Koji je kraj najljepši?
Marko: Za mene primorski, Dalmacija je jedna od najljepših regija.', 'Darja: Чому люди в Загор’ї говорять інакше?
Marko: Це кайкавське наріччя. У Далмації звучить знову інакше.
Darja: А Ліка?
Marko: Ліка — континентальна, зими там найхолодніші.
Darja: Який край найгарніший?
Marko: Для мене приморський, Далмація — один із найгарніших регіонів.', 'Діалог «Як вони говорять?»: «Zašto ljudi u Zagorju drugačije govore?» — «To je kajkavsko narječje. U Dalmaciji zvuči opet drugačije.», тобто «Це кайкавське наріччя. У Далмації звучить знову інакше.».', (select id from public.lessons where id = '8633c234-d638-57f1-ad92-1c78be43fb07'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8fb3f98d-d808-554c-960c-263d29b2415e', v_aid, 9, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Tata, žive li ovdje medvjedi?', '["Живуть, і вовки, і рисі, але вони дуже полохливі.", "Мабуть, ні. Але зранку я бачив козулю й оленя.", "Білка! А вночі почуємо сову."]'::jsonb, 0, null, '{}'::text[], null, 'Filip: Tata, žive li ovdje medvjedi?
Luka: Žive, i vukovi i risovi, ali su jako plahi.
Filip: Hoćemo li vidjeti nekog medvjeda?
Luka: Vjerojatno nećemo. Ali jutros sam vidio srnu i jelena.
Filip: A što je ono na drvetu?
Luka: Vjeverica! A noću ćemo čuti sovu.', 'Filip: Тату, тут живуть ведмеді?
Luka: Живуть, і вовки, і рисі, але вони дуже полохливі.
Filip: Ми побачимо якогось ведмедя?
Luka: Мабуть, ні. Але зранку я бачив козулю й оленя.
Filip: А що ото на дереві?
Luka: Білка! А вночі почуємо сову.', 'Діалог «У Горському Котарі»: «Tata, žive li ovdje medvjedi?» — «Žive, i vukovi i risovi, ali su jako plahi.», тобто «Живуть, і вовки, і рисі, але вони дуже полохливі.».', (select id from public.lessons where id = '88e6f563-29dd-5e5d-865b-67fa47474b07'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d8fa0253-f0ac-5fdd-85d5-89fa876d93d6', v_aid, 10, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Звідки ти, з якого краю?». Що ви скажете?', null, '["Kakvo će biti vrijeme sutra?", "Koliko košta ležaljka?", "Iz kojeg si kraja?"]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Звідки ти, з якого краю?» — «Iz kojeg si kraja?».', (select id from public.lessons where id = '8633c234-d638-57f1-ad92-1c78be43fb07'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c7a66cd6-9eff-5fb5-8bce-c45de7db2521', v_aid, 11, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Далмація найгарніша». Що ви скажете?', null, '["Volim prirodu.", "Gledaj, dupini!", "Dalmacija je najljepša."]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Далмація найгарніша.» — «Dalmacija je najljepša.».', (select id from public.lessons where id = '8633c234-d638-57f1-ad92-1c78be43fb07'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f0d65171-413c-58dd-ab3f-2f3970a65a90', v_aid, 12, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «пірнання; дайвінг»', null, '[]'::jsonb, null, 'ronjenje', '{}'::text[], null, null, null, '«пірнання; дайвінг» — ronjenje.', (select id from public.lessons where id = '71ab330d-abbe-57a7-870e-77e59daf3627'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4fc1bdf8-1d58-59a1-b2fb-69a58e8f5a7f', v_aid, 13, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Коли відправляється пором?»', null, '["trajekt?", "polazi", "Kada"]'::jsonb, null, 'Kada polazi trajekt?', array['Kada trajekt polazi?']::text[], null, null, null, '«Коли відправляється пором?» — «Kada polazi trajekt?».', (select id from public.lessons where id = '71ab330d-abbe-57a7-870e-77e59daf3627'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b157de01-1016-5ac1-8d8e-5ed0eb88ef50', v_aid, 14, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Як було в Задарі?»', null, '[]'::jsonb, null, 'Kako je bilo u Zadru?', '{}'::text[], null, null, null, '«Як було в Задарі?» — «Kako je bilo u Zadru?».', (select id from public.lessons where id = '9a44edc5-7e46-5377-bfcb-20cd93ac333b'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A1 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
