  ('bba10de0-d3de-5664-abdd-a1cf871fa851', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мамо, прочитай мені казку на ніч!", "Звісно, це найкращий гарнір!", "Про дракона! І щоб був щасливий кінець."]'::jsonb, 2, null, '{}'::text[], 'O zmaju! I neka ima sretan kraj.', null, null, 'Прозвучало: «O zmaju! I neka ima sretan kraj.» — «Про дракона! І щоб був щасливий кінець.».', (select id from public.lessons where id = '8bb4331d-c7c0-5039-acf9-756684424039'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c869f239-1279-5a28-a54e-aa88f457ae07', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Хто такі дзвонарі?", "Ти бачила статую Григорія Нинського?", "Де ви зустрічатимете Новий рік?"]'::jsonb, 0, null, '{}'::text[], 'Tko su zvončari?', null, null, 'Прозвучало: «Tko su zvončari?» — «Хто такі дзвонарі?».', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7e9eec80-67d3-5b53-9526-86776b85889a', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А Тіла Христового? Воно завжди в четвер.", "Для мене самоборська кремшніта, але скуштуй і фрітуле.", "Без проблем, ось нові. Спробуйте їх тут."]'::jsonb, 1, null, '{}'::text[], 'Za mene samoborska kremšnita, ali probaj i fritule.', null, null, 'Прозвучало: «Za mene samoborska kremšnita, ali probaj i fritule.» — «Для мене самоборська кремшніта, але скуштуй і фрітуле.».', (select id from public.lessons where id = 'f1b2093d-9699-59af-92b9-ed7bdf7fad49'), 'PUBLISHED', 'claude_assessment_v5'),
  ('084c54de-f7bd-5967-bfd9-e84bdb1f61f9', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Що роблять гості в багатьох домах?', 'Hrvatski običaji: kava i gosti', '["Знімають взуття", "Приносять вино", "Готують обід"]'::jsonb, 0, null, '{}'::text[], null, 'U Hrvatskoj ljudi često idu na kavu. Kava nije samo kava – to je vrijeme za prijatelje. Kad idete u goste, donesite nešto malo, na primjer kolač. U puno kuća gosti se izuju. Domaćica uvijek nudi jelo i piće, jer su Hrvati vrlo gostoljubivi.', 'У Хорватії люди часто ходять на каву. Кава — це не просто кава, це час для друзів. Коли йдете в гості, принесіть щось невелике, наприклад тістечко. У багатьох домах гості знімають взуття. Господиня завжди пропонує їжу й напої, бо хорвати дуже гостинні.', 'Текст «Хорватські звичаї: кава й гості». Правильна відповідь: «Знімають взуття».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('22edf531-37ba-5ac6-9898-cf1bd2db6101', v_aid, 5, 'A1', 'reading', 'understand', 'multiple_choice', 'Що варто принести в гості?', 'Hrvatski običaji: kava i gosti', '["Щось невелике, наприклад тістечко", "Нічого", "Дорогий подарунок"]'::jsonb, 0, null, '{}'::text[], null, 'U Hrvatskoj ljudi često idu na kavu. Kava nije samo kava – to je vrijeme za prijatelje. Kad idete u goste, donesite nešto malo, na primjer kolač. U puno kuća gosti se izuju. Domaćica uvijek nudi jelo i piće, jer su Hrvati vrlo gostoljubivi.', 'У Хорватії люди часто ходять на каву. Кава — це не просто кава, це час для друзів. Коли йдете в гості, принесіть щось невелике, наприклад тістечко. У багатьох домах гості знімають взуття. Господиня завжди пропонує їжу й напої, бо хорвати дуже гостинні.', 'Текст «Хорватські звичаї: кава й гості». Правильна відповідь: «Щось невелике, наприклад тістечко».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('a94ca310-c4c1-51c9-8d36-b06a06aafc87', v_aid, 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoćemo li bojiti jaja?', '["Preko videopoziva i maila.", "Hoćemo! Djeca će napraviti pisanice.", "Super! Upoznala sam cijeli tim."]'::jsonb, 1, null, '{}'::text[], 'Hoćemo li bojiti jaja?', null, null, 'Діалог «Великдень»: «Hoćemo li bojiti jaja?» (Будемо фарбувати яйця?) — «Hoćemo! Djeca će napraviti pisanice.» (Будемо! Діти зроблять писанки.).', (select id from public.lessons where id = 'f67bd38c-a41c-51df-b9c0-081737600fce'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c713d1ca-4095-564c-9310-a7e65edd03b5', v_aid, 7, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Zašto toliko zvone?', '["To je stari običaj. Tjeraju zimu i zle duhove.", "U kutiji, na dnu. I vijci su u maloj vrećici.", "Petnaest eura mjesečno, s dvadeset giga podataka."]'::jsonb, 0, null, '{}'::text[], 'Zašto toliko zvone?', null, null, 'Діалог «Дзвонарі»: «Zašto toliko zvone?» (Чому вони так дзвонять?) — «To je stari običaj. Tjeraju zimu i zle duhove.» (Це давній звичай. Вони проганяють зиму й злих духів.).', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('970afc29-ab8a-5b4c-b30b-8822ef71572e', v_aid, 8, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Peka zvuči odlično. Koliko se čeka?', '["Balet. Ulaznice su još u prodaji.", "Objavu o tečaju hrvatskog, tražim partnera za razgovor.", "Oko sat vremena. Za početak preporučujem pršut i paški sir."]'::jsonb, 2, null, '{}'::text[], 'Peka zvuči odlično. Koliko se čeka?', null, null, 'Діалог «У конобі»: «Peka zvuči odlično. Koliko se čeka?» (Пека звучить чудово. Скільки чекати?) — «Oko sat vremena. Za početak preporučujem pršut i paški sir.» (Близько години. Для початку раджу пршут і паґський сир.).', (select id from public.lessons where id = 'f1b2093d-9699-59af-92b9-ed7bdf7fad49'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7ad8cad9-ab5b-5fd3-afdb-4d46716860c5', v_aid, 9, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kada su izgradili ove zidine?', '["Це Ловрієнац. Колись там жили вояки.", "Їх будували століттями, ще в середньовіччі.", "Ласкаво просимо! Я ваш туристичний гід."]'::jsonb, 1, null, '{}'::text[], null, 'Ivan: Dobro došli! Ja sam vaš turistički vodič.
Daša: Kada su izgradili ove zidine?
Ivan: Gradili su ih stoljećima, još u srednjem vijeku.
Daša: A što je ona velika tvrđava?
Ivan: To je Lovrijenac. Nekada su ondje živjeli vojnici.
Daša: Možemo li se popeti gore?', 'Ivan: Ласкаво просимо! Я ваш туристичний гід.
Daša: Коли збудували ці мури?
Ivan: Їх будували століттями, ще в середньовіччі.
Daša: А що це за велика фортеця?
Ivan: Це Ловрієнац. Колись там жили вояки.
Daša: Можна піднятися нагору?', 'Діалог «Екскурсія Дубровником»: «Kada su izgradili ove zidine?» — «Gradili su ih stoljećima, još u srednjem vijeku.», тобто «Їх будували століттями, ще в середньовіччі.».', (select id from public.lessons where id = 'd9ef1de4-f4db-590e-bafd-474f84c8e03f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a4348e34-b4bd-5255-ba22-875da1a79e5e', v_aid, 10, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Marko, radiš li tridesetog svibnja?', '["П’ятого серпня — День перемоги, а п’ятнадцятого — Успіння Богородиці.", "Ні, це День державності, неробочий день.", "Добрий вечір! Сьогодні фірмова страва — пека з восьминога."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Marko, radiš li tridesetog svibnja?
Marko: Ne, to je Dan državnosti, neradni dan.
Daša: A Tijelovo? Ono je uvijek u četvrtak.
Marko: Onda uzmem petak i imam produženi vikend!
Daša: A u kolovozu?
Marko: Petog kolovoza je Dan pobjede, a petnaestog Velika Gospa.', 'Daša: Марко, ти працюєш тридцятого травня?
Marko: Ні, це День державності, неробочий день.
Daša: А Тіла Христового? Воно завжди в четвер.
Marko: Тоді візьму п’ятницю, і в мене довгі вихідні!
Daša: А в серпні?
Marko: П’ятого серпня — День перемоги, а п’ятнадцятого — Успіння Богородиці.', 'Діалог «Календар свят»: «Marko, radiš li tridesetog svibnja?» — «Ne, to je Dan državnosti, neradni dan.», тобто «Ні, це День державності, неробочий день.».', (select id from public.lessons where id = '33c041a0-e71a-55c1-94c8-64941876c6d2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('36758f7b-b68a-51ce-99c7-3f98e78703a4', v_aid, 11, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Яка мораль цієї казки?». Що ви скажете?', null, '["Koja je pouka ove priče?", "Koji je vaš specijalitet?", "Živjeli!"]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Яка мораль цієї казки?» — «Koja je pouka ove priče?».', (select id from public.lessons where id = '8bb4331d-c7c0-5039-acf9-756684424039'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e6d73b7e-2ef1-5daa-ad20-d750cc20cc12', v_aid, 12, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я йду на карнавал з колегами». Що ви скажете?', null, '["Idem na karneval s kolegama.", "Sretan imendan!", "Ovo je najbolje jelo."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Я йду на карнавал з колегами.» — «Idem na karneval s kolegama.».', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('622a7574-6964-5bce-b66e-ed03a2232ed1', v_aid, 13, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «традиція»', null, '[]'::jsonb, null, 'tradicija', '{}'::text[], null, null, null, '«традиція» — tradicija.', (select id from public.lessons where id = 'f67bd38c-a41c-51df-b9c0-081737600fce'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ff70cd3d-a6a7-5f88-98bf-fdc8792a1417', v_aid, 14, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ми гуляли вузькими вуличками.»', null, '["Šetali", "smo", "uličicama.", "uskim"]'::jsonb, null, 'Šetali smo uskim uličicama.', array['Uskim uličicama smo šetali.']::text[], null, null, null, '«Ми гуляли вузькими вуличками.» — «Šetali smo uskim uličicama.».', (select id from public.lessons where id = 'd9ef1de4-f4db-590e-bafd-474f84c8e03f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f3e69527-b765-5653-977c-72e3e704861b', v_aid, 15, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Пршут смачніший за шинку.»', null, '["šunke.", "je", "ukusniji", "od", "Pršut"]'::jsonb, null, 'Pršut je ukusniji od šunke.', '{}'::text[], null, null, null, '«Пршут смачніший за шинку.» — «Pršut je ukusniji od šunke.».', (select id from public.lessons where id = 'f1b2093d-9699-59af-92b9-ed7bdf7fad49'), 'PUBLISHED', 'claude_assessment_v5'),
  ('68f338d4-dff7-5775-9b27-66479b73e6b9', v_aid, 16, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я не вмію зав’язувати краватку.»', null, '[]'::jsonb, null, 'Ne znam vezati kravatu.', '{}'::text[], null, null, null, '«Я не вмію зав’язувати краватку.» — «Ne znam vezati kravatu.».', (select id from public.lessons where id = '5ae02c5f-7ba1-5b59-be71-f744d6e9b169'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A1 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
end $$;

-- Перевірка модуля A1.12 · 14 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a1-m12' and cefr = 'A1';
  if v_aid is null then raise exception 'Немає тесту a1-m12 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = 'eeeaf934-8914-527a-ae07-f97691d270a2') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '5a6eadc1-9da1-52c0-a50d-943a3fbffe70'::uuid then
    raise exception 'Тест a1-m12 прив’язаний не до модуля A1.12 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 14 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~7 хв.', estimated_minutes = 7 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('eeeaf934-8914-527a-ae07-f97691d270a2', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так. Мене цікавить і ощадний рахунок. Який відсоток?", "Марко, як тут знімають гроші?", "Чотири. Чи є вільні місця?"]'::jsonb, 1, null, '{}'::text[], 'Marko, kako se ovdje podiže novac?', null, null, 'Прозвучало: «Marko, kako se ovdje podiže novac?» — «Марко, як тут знімають гроші?».', (select id from public.lessons where id = '1c468857-b9aa-5143-aa84-6ea02aa2443c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d597c9bc-1e8d-5ab4-bf9b-6d8238c05398', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Можна користуватися словником у телефоні?", "Я ходжу зранку чи по обіді?", "П’ятдесят два євро. Бажаєте пакет?"]'::jsonb, 1, null, '{}'::text[], 'Idem li ujutro ili popodne?', null, null, 'Прозвучало: «Idem li ujutro ili popodne?» — «Я ходжу зранку чи по обіді?».', (select id from public.lessons where id = '7c8e16ec-03f3-55dd-a61a-fb59c2401692'), 'PUBLISHED', 'claude_assessment_v5'),
  ('beb8bfe4-9ff6-57dd-bec5-d15000fa7d02', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Засвідчити можна в нотаріуса, це поруч.", "Добрий день, мене цікавить інтенсивний курс хорватської.", "Як у неї справи? Вона ще погано говорить хорватською."]'::jsonb, 1, null, '{}'::text[], 'Dobar dan, zanima me intenzivni tečaj hrvatskog.', null, null, 'Прозвучало: «Dobar dan, zanima me intenzivni tečaj hrvatskog.» — «Добрий день, мене цікавить інтенсивний курс хорватської.».', (select id from public.lessons where id = '11b565a4-1e2a-50d2-8d9d-c05e84371402'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4fe8c8e7-b8ed-5711-ba4e-926c227c786a', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Скільки олівців потрібно?', 'Popis pribora za 1. razred', '["П’ять", "Два", "Один"]'::jsonb, 1, null, '{}'::text[], null, 'POPIS PRIBORA – 1. RAZRED
Školska torba, pernica, dvije olovke, gumica, šiljilo, ravnalo, bojice, vodene boje, škare i omot za knjige.
Udžbenike i radne bilježnice kupite u trgovini.
Na sve stvari napišite ime djeteta.
Razrednica', 'СПИСОК ПРИЛАДДЯ — 1 КЛАС
Шкільний рюкзак, пенал, два олівці, гумка, стругачка, лінійка, кольорові олівці, акварельні фарби, ножиці й обкладинка для книжок.
Підручники й робочі зошити купіть у магазині.
На всіх речах напишіть ім’я дитини.
Класна керівниця', 'Текст «Список приладдя для 1 класу». Правильна відповідь: «Два».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('4a7ea633-57fb-5f88-8720-8d374ef2cefa', v_aid, 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Obična ili brza pošta?', '["Obično sutra. Šaljemo ga na vašu adresu.", "Jutros je ulovljena, kao i brancin.", "Obična. Imam i obavijest, trebam preuzeti pošiljku."]'::jsonb, 2, null, '{}'::text[], 'Obična ili brza pošta?', null, null, 'Діалог «На пошті»: «Obična ili brza pošta?» (Звичайна чи експрес-пошта?) — «Obična. Imam i obavijest, trebam preuzeti pošiljku.» (Звичайна. У мене ще повідомлення, мені треба забрати відправлення.).', (select id from public.lessons where id = '1c468857-b9aa-5143-aa84-6ea02aa2443c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('73c60358-8f90-5582-aa84-955539fb6a29', v_aid, 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ima li moja kći hrvatski jezik svaki dan?', '["Super! Upoznala sam cijeli tim.", "Ima, a tjelesni odgoj dvaput tjedno.", "Uglavnom da, ova stambena zgrada je mirna."]'::jsonb, 1, null, '{}'::text[], 'Ima li moja kći hrvatski jezik svaki dan?', null, null, 'Діалог «Батьківські збори»: «Ima li moja kći hrvatski jezik svaki dan?» (Чи в моєї доньки хорватська мова щодня?) — «Ima, a tjelesni odgoj dvaput tjedno.» (Так, а фізкультуру двічі на тиждень.).', (select id from public.lessons where id = '7c8e16ec-03f3-55dd-a61a-fb59c2401692'), 'PUBLISHED', 'claude_assessment_v5'),
  ('15be906b-ef3c-5de8-ab29-d69d36371c27', v_aid, 7, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kolika je mjesečna naknada?', '["Za to postoji cjepivo, pitajte doktoricu.", "Natašte, ujutro. Progutajte ih s puno vode.", "Tri eura. Uz račun dobivate debitnu karticu i mobilno bankarstvo."]'::jsonb, 2, null, '{}'::text[], 'Kolika je mjesečna naknada?', null, null, 'Діалог «Відкриваю рахунок»: «Kolika je mjesečna naknada?» (Яка щомісячна плата?) — «Tri eura. Uz račun dobivate debitnu karticu i mobilno bankarstvo.» (Три євро. До рахунку ви отримуєте дебетову картку й мобільний банкінг.).', (select id from public.lessons where id = 'fee5b77b-dc3b-5fd5-818a-c5496e95c23b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e41c5110-5c1a-59de-905b-f03a0e397fe0', v_aid, 8, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što trebam donijeti?', '["Паспорт, підтвердження житла й підтвердження коштів на утримання.", "Сплатіть його до подання. Рішення отримаєте поштою.", "Добрий день, у мене наступного місяця спливає тимчасове проживання."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Dobar dan, moj privremeni boravak istječe sljedeći mjesec.
Službenica: Zahtjev za produljenje predajte najkasnije šezdeset dana prije isteka.
Daša: Što trebam donijeti?
Službenica: Putovnicu, dokaz o smještaju i dokaz o sredstvima za uzdržavanje.
Daša: A upravna pristojba?
Službenica: Platite je prije predaje. Rješenje dobivate poštom.', 'Daša: Добрий день, у мене наступного місяця спливає тимчасове проживання.
Službenica: Заяву на продовження подайте не пізніше ніж за шістдесят днів до закінчення терміну.
Daša: Що мені треба принести?
Službenica: Паспорт, підтвердження житла й підтвердження коштів на утримання.
Daša: А адміністративний збір?
Službenica: Сплатіть його до подання. Рішення отримаєте поштою.', 'Діалог «У відділі для іноземців»: «Što trebam donijeti?» — «Putovnicu, dokaz o smještaju i dokaz o sredstvima za uzdržavanje.», тобто «Паспорт, підтвердження житла й підтвердження коштів на утримання.».', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f26f8d88-c0ac-5dd7-b01d-83d690c4eaa7', v_aid, 9, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Ne, hvala. Mogu li dobiti dopušteno prekoračenje?', '["Можна, до суми однієї зарплати.", "Прошу. Бачу, у вас регулярні надходження.", "Мені потрібна виписка з рахунку за останні три місяці."]'::jsonb, 0, null, '{}'::text[], null, 'Darja: Trebam izvod s računa za zadnja tri mjeseca.
Službenik: Izvolite. Vidim da imate redovite uplate.
Darja: Da. Zanima me i štedni račun. Kolika je kamata?
Službenik: Dva posto godišnje. Želite li i kreditnu karticu?
Darja: Ne, hvala. Mogu li dobiti dopušteno prekoračenje?
Službenik: Možete, do iznosa jedne plaće.', 'Darja: Мені потрібна виписка з рахунку за останні три місяці.
Službenik: Прошу. Бачу, у вас регулярні надходження.
Darja: Так. Мене цікавить і ощадний рахунок. Який відсоток?
Službenik: Два відсотки на рік. Бажаєте також кредитну картку?
Darja: Ні, дякую. А можна дозволений овердрафт?
Službenik: Можна, до суми однієї зарплати.', 'Діалог «Виписка й заощадження»: «Ne, hvala. Mogu li dobiti dopušteno prekoračenje?» — «Možete, do iznosa jedne plaće.», тобто «Можна, до суми однієї зарплати.».', (select id from public.lessons where id = 'fee5b77b-dc3b-5fd5-818a-c5496e95c23b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0fbd2566-78f6-5aee-871c-128b6119eedc', v_aid, 10, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Яка плата за рахунок?». Що ви скажете?', null, '["Trebam debitnu karticu.", "Kolika je naknada za račun?", "Koja je vaša razina?"]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Яка плата за рахунок?» — «Kolika je naknada za račun?».', (select id from public.lessons where id = 'fee5b77b-dc3b-5fd5-818a-c5496e95c23b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5fa474ba-d8a6-5070-aaed-76464fb7e6ff', v_aid, 11, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Коли спливає ваш дозвіл?». Що ви скажете?', null, '["Gdje je javni bilježnik?", "Kada vam istječe dozvola?", "Idem na tečaj za početnike."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Коли спливає ваш дозвіл?» — «Kada vam istječe dozvola?».', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('1ea04158-3f12-51f6-b642-197215d309d8', v_aid, 12, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «офіційне рішення»', null, '[]'::jsonb, null, 'rješenje', '{}'::text[], null, null, null, '«офіційне рішення» — rješenje.', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('393169f9-e038-5793-8031-7bea9fdfe021', v_aid, 13, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я хочу записати доньку в садок.»', null, '["upisati", "u", "Želim", "kćer", "vrtić."]'::jsonb, null, 'Želim upisati kćer u vrtić.', array['Želim kćer upisati u vrtić.']::text[], null, null, null, '«Я хочу записати доньку в садок.» — «Želim upisati kćer u vrtić.».', (select id from public.lessons where id = '42c31cfb-8680-5450-8453-245f3abd475a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('dce2fb10-4133-5adc-a347-4e0aa7adc1d5', v_aid, 14, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Де розклад уроків?»', null, '[]'::jsonb, null, 'Gdje je raspored sati?', '{}'::text[], null, null, null, '«Де розклад уроків?» — «Gdje je raspored sati?».', (select id from public.lessons where id = '7c8e16ec-03f3-55dd-a61a-fb59c2401692'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A1 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
