-- Перевірка модуля A1.13 · 12 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a1-m13' and cefr = 'A1';
  if v_aid is null then raise exception 'Немає тесту a1-m13 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '301dabbf-4805-513f-9884-0bf4bfff4bf0') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '34064af4-9715-5f07-b87c-a5e28eb8127b'::uuid then
    raise exception 'Тест a1-m13 прив’язаний не до модуля A1.13 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('301dabbf-4805-513f-9884-0bf4bfff4bf0', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Даріє, чим ти займаєшся у вільний час?", "Даріє, ти сумуєш за Україною?", "Маєш якусь пораду для тих, хто тільки приїжджає?"]'::jsonb, 2, null, '{}'::text[], 'Imaš li neki savjet za one koji tek dolaze?', null, null, 'Прозвучало: «Imaš li neki savjet za one koji tek dolaze?» — «Маєш якусь пораду для тих, хто тільки приїжджає?».', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v5'),
  ('83e23c55-ed24-5464-9737-e02821966c06', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дашо, коли ти переїхала до Хорватії?", "Який у тебе найгарніший спогад з першого року?", "Як ти тут подружилася з людьми?"]'::jsonb, 1, null, '{}'::text[], 'Koje ti je najljepše sjećanje iz prve godine?', null, null, 'Прозвучало: «Koje ti je najljepše sjećanje iz prve godine?» — «Який у тебе найгарніший спогад з першого року?».', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6f4dd183-fdaf-58e0-a36c-ec8402d996da', v_aid, 3, 'A1', 'reading', 'understand', 'multiple_choice', 'Хто перекладає документи?', 'Obavijest MUP-a', '["Присяжний перекладач", "Сам заявник", "Будь-хто"]'::jsonb, 0, null, '{}'::text[], null, 'OBAVIJEST ZA STRANCE
Zahtjev za privremeni boravak predajete u policijskoj upravi u gradu gdje živite.
Trebate: važeću putovnicu, fotografiju, dokaz o smještaju i zdravstveno osiguranje.
Dokumente na ukrajinskom jeziku prevodi sudski tumač.
Na šalter dolazite s brojem iz automata. Radno vrijeme: 8 – 15 sati.
Ako ne razumijete, pitajte na šalteru. Dođite na vrijeme!', 'ОГОЛОШЕННЯ ДЛЯ ІНОЗЕМЦІВ
Заяву на тимчасове перебування подаєте в поліцейському управлінні в місті, де ви живете.
Потрібно: чинний паспорт, фотографія, підтвердження житла й медичне страхування.
Документи українською мовою перекладає присяжний перекладач.
До віконця підходите з номером з автомата. Години роботи: з 8:00 до 15:00.
Якщо не розумієте, запитайте у віконці. Приходьте вчасно!', 'Текст «Документи в MUP». Правильна відповідь: «Присяжний перекладач».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('22db7ccd-5e42-5bda-8db3-c9a56db72290', v_aid, 4, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koja je vaša struka?', '["Rukomet ili košarka, ovdje su jako popularni.", "U subotu će puhati bura, bit će hladno i vjetrovito.", "Po struci sam knjigovođa, a sada radim u trgovini."]'::jsonb, 2, null, '{}'::text[], 'Koja je vaša struka?', null, null, 'Діалог «Розкажіть про себе»: «Koja je vaša struka?» (Яка ваша спеціальність?) — «Po struci sam knjigovođa, a sada radim u trgovini.» (За фахом я бухгалтерка, а зараз працюю в магазині.).', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5bac17da-8ce0-58f3-b230-b3ca97bc0547', v_aid, 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dašo, koji su tvoji ciljevi za sljedeću godinu?', '["Preko e-Građana, ne moraš ići u ured.", "Željeznica ima zamjenski autobus ispred kolodvora.", "Usavršit ću hrvatski i položiti ispit B1."]'::jsonb, 2, null, '{}'::text[], 'Dašo, koji su tvoji ciljevi za sljedeću godinu?', null, null, 'Діалог «Плани на рік»: «Dašo, koji su tvoji ciljevi za sljedeću godinu?» (Дашо, які в тебе цілі на наступний рік?) — «Usavršit ću hrvatski i položiti ispit B1.» (Я вдосконалю хорватську й складу іспит B1.).', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4b35dd20-6c09-585b-bfa1-e63e844d6083', v_aid, 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koja je najveća prednost života ovdje?', '["Sigurnost i more. A nedostatak — birokracija!", "Pekmez od marelica, ako ga još imamo.", "Obično mjesec dana. Kad ti odobre, dobiješ novu iskaznicu."]'::jsonb, 0, null, '{}'::text[], 'Koja je najveća prednost života ovdje?', null, null, 'Діалог «Залишитися чи ні?»: «Koja je najveća prednost života ovdje?» (Яка найбільша перевага життя тут?) — «Sigurnost i more. A nedostatak — birokracija!» (Безпека й море. А недолік — бюрократія!).', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v5'),
  ('474f6966-c012-555f-a45a-b90017e45a3e', v_aid, 7, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Darja, čime se baviš u slobodno vrijeme?', '["Це одразу видно. І ти дуже відкрита.", "Я комунікабельна, люблю знайомитися з новими людьми.", "Я цікавлюся фотографією та історією."]'::jsonb, 2, null, '{}'::text[], null, 'Ivana: Darja, čime se baviš u slobodno vrijeme?
Darja: Zanimam se za fotografiju i povijest.
Ivana: Vidi se da si znatiželjna!
Darja: Jesam. A ti? Koja je tvoja najbolja osobina?
Ivana: Komunikativna sam, volim upoznavati nove ljude.
Darja: To se odmah vidi. I jako si otvorena.', 'Ivana: Даріє, чим ти займаєшся у вільний час?
Darja: Я цікавлюся фотографією та історією.
Ivana: Видно, що ти допитлива!
Darja: Так. А ти? Яка твоя найкраща риса?
Ivana: Я комунікабельна, люблю знайомитися з новими людьми.
Darja: Це одразу видно. І ти дуже відкрита.', 'Діалог «Нове знайомство»: «Darja, čime se baviš u slobodno vrijeme?» — «Zanimam se za fotografiju i povijest.», тобто «Я цікавлюся фотографією та історією.».', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7b4b634f-23a8-53fb-b086-919bd44dbaff', v_aid, 8, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što ti je bilo najteže?', '["Три роки тому. Початок був дуже важкий.", "Так! Мене здивувало, скільки часу люди тут мають на каву.", "Мова й документи. Але крок за кроком я дала собі раду."]'::jsonb, 2, null, '{}'::text[], null, 'Marko: Dašo, kad si se doselila u Hrvatsku?
Daša: Prije tri godine. Početak je bio jako težak.
Marko: Što ti je bilo najteže?
Daša: Jezik i papiri. Ali korak po korak, snašla sam se.
Marko: A jesi li se brzo navikla na naš mentalitet?
Daša: Jesam! Iznenadilo me koliko ljudi ovdje imaju vremena za kavu.', 'Marko: Дашо, коли ти переїхала до Хорватії?
Daša: Три роки тому. Початок був дуже важкий.
Marko: Що тобі було найважче?
Daša: Мова й документи. Але крок за кроком я дала собі раду.
Marko: А ти швидко звикла до нашого менталітету?
Daša: Так! Мене здивувало, скільки часу люди тут мають на каву.', 'Діалог «Перший рік»: «Što ti je bilo najteže?» — «Jezik i papiri. Ali korak po korak, snašla sam se.», тобто «Мова й документи. Але крок за кроком я дала собі раду.».', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b2b2cf7a-1567-5d1b-b04c-15e40ce945bc', v_aid, 9, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я надійна й терпляча». Що ви скажете?', null, '["Korak po korak.", "Koji su tvoji ciljevi?", "Pouzdana sam i strpljiva."]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Я надійна й терпляча.» — «Pouzdana sam i strpljiva.».', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a4b5fe31-b5b5-5459-9b0e-54991b98c623', v_aid, 10, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «звикнути»', null, '[]'::jsonb, null, 'naviknuti se', '{}'::text[], null, null, null, '«звикнути» — naviknuti se.', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('18a268e6-a1b9-5afc-bf26-2c8e0667aa47', v_aid, 11, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я виросла в Києві.»', null, '["sam", "Kijevu.", "Odrasla", "u"]'::jsonb, null, 'Odrasla sam u Kijevu.', array['U Kijevu sam odrasla.']::text[], null, null, null, '«Я виросла в Києві.» — «Odrasla sam u Kijevu.».', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v5'),
  ('23d71156-8f2b-52b5-9cd3-4f9e3ca428c4', v_aid, 12, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я вдосконалю хорватську.»', null, '[]'::jsonb, null, 'Usavršit ću hrvatski.', '{}'::text[], null, null, null, '«Я вдосконалю хорватську.» — «Usavršit ću hrvatski.».', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A1 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
