-- Перевірка середини рівня A1 · 30 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a1-mid' and cefr = 'A1';
  if v_aid is null then raise exception 'Немає тесту a1-mid — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '07f25071-b4e2-50f8-be3c-a2770944f1d5') then return; end if;  -- уже оновлено
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Середина рівня (модулі A1.1–A1.6): 30 завдань на 4 навички. ~15 хв.', estimated_minutes = 15 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('07f25071-b4e2-50f8-be3c-a2770944f1d5', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["У тебе бувають нічні кошмари?", "Дашо, як ти любиш проводити вихідні?", "А корм для собак?"]'::jsonb, 2, null, '{}'::text[], 'A hrana za pse?', null, null, 'Прозвучало: «A hrana za pse?» — «А корм для собак?».', (select id from public.lessons where id = '1968c7d5-4e3a-5b1e-92f6-88df711e9c54'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e80b48c0-5a37-5366-a119-6daadc76d49b', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Можна. На яке ім’я?", "Опівдні. Що сьогодні в їдальні?", "А залишки салату з миски?"]'::jsonb, 1, null, '{}'::text[], 'U podne. Što je danas u menzi?', null, null, 'Прозвучало: «U podne. Što je danas u menzi?» — «Опівдні. Що сьогодні в їдальні?».', (select id from public.lessons where id = '2c192d05-f259-53b6-a6ec-55ebfb25ec01'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ec3823fa-9c33-545f-bae9-a80cab3b4773', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Двадцять два. У мене велика валіза.", "На головній дорозі затор, поїдемо об’їзною.", "З вихлопом усе гаразд, а от фільтр треба міняти."]'::jsonb, 2, null, '{}'::text[], 'Ispuh je u redu, ali filter treba mijenjati.', null, null, 'Прозвучало: «Ispuh je u redu, ali filter treba mijenjati.» — «З вихлопом усе гаразд, а от фільтр треба міняти.».', (select id from public.lessons where id = 'cd5db261-a421-511d-8100-f86bf2335bbe'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0a2aab4c-51b4-5732-9b81-4275dcab9055', v_aid, 4, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Можна сушити білизну на горищі?", "А світло на сходах?", "Добрий день, де можна прочитати правила будинку?"]'::jsonb, 2, null, '{}'::text[], 'Dobar dan, gdje mogu pročitati kućni red?', null, null, 'Прозвучало: «Dobar dan, gdje mogu pročitati kućni red?» — «Добрий день, де можна прочитати правила будинку?».', (select id from public.lessons where id = 'f296bc84-8059-5981-a5b9-9d4531627e18'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4815b2f4-5698-5066-b0b9-871f46f299c4', v_aid, 5, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дашо, коли ти починаєш працювати?", "А твоя сестра?", "Чи мушу я працювати у вихідні?"]'::jsonb, 1, null, '{}'::text[], 'A tvoja sestra?', null, null, 'Прозвучало: «A tvoja sestra?» — «А твоя сестра?».', (select id from public.lessons where id = 'b369f01f-4a84-57b4-98cb-150d236f4d7f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('84c6d4bf-328c-5b73-9941-e0345d1f99a9', v_aid, 6, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли виносити сміття?', 'Odvajanje otpada', '["Уранці в неділю", "Увечері, до восьмої", "Будь-коли"]'::jsonb, 1, null, '{}'::text[], null, 'ODVAJAJTE OTPAD!
Plava kanta: papir i karton.
Žuta kanta: plastika i limenke.
Zelena kanta: staklo.
Smeđa kanta: ostaci hrane.
Crna kanta: drugo smeće.
Smeće iznosimo navečer, prije osam sati. Velike stvari ne ostavljajte pored kanti. Hvala što čuvate naš grad!', 'СОРТУЙТЕ ВІДХОДИ!
Синій контейнер: папір і картон.
Жовтий контейнер: пластик і бляшанки.
Зелений контейнер: скло.
Коричневий контейнер: залишки їжі.
Чорний контейнер: інше сміття.
Сміття виносимо ввечері, до восьмої години. Великих речей не залишайте біля контейнерів. Дякуємо, що бережете наше місто!', 'Текст «Сміття й переробка». Правильна відповідь: «Увечері, до восьмої».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('dd833e61-eb7d-58ac-a032-597c83b11875', v_aid, 7, 'A1', 'reading', 'understand', 'multiple_choice', 'Скільки часу дійсний квиток?', 'Kako kupiti kartu na automatu', '["90 хвилин", "30 хвилин", "Один день"]'::jsonb, 0, null, '{}'::text[], null, '1. Odaberite jezik.
2. Odaberite kartu: jednosmjernu ili povratnu.
3. Upišite broj putnika.
4. Platite karticom ili kovanicama.
5. Uzmite kartu i ostatak novca.
Karta vrijedi 90 minuta. Poništite je u tramvaju ili autobusu.', '1. Виберіть мову.
2. Виберіть квиток: в один бік чи туди й назад.
3. Введіть кількість пасажирів.
4. Заплатіть карткою або монетами.
5. Заберіть квиток і решту.
Квиток дійсний 90 хвилин. Прокомпостуйте його в трамваї чи автобусі.', 'Текст «Як купити квиток в автоматі». Правильна відповідь: «90 хвилин».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('4c10b1f4-153f-55a9-86a7-a19f44fc4809', v_aid, 8, 'A1', 'reading', 'understand', 'multiple_choice', 'Що коштує 2 € цього тижня?', 'Nova pekara', '["Бурек", "Хліб", "Кава з собою і круасан"]'::jsonb, 2, null, '{}'::text[], null, 'NOVA PEKARA U VAŠEM KVARTU!
Svaki dan svježi kruh, peciva i burek.
Otvoreno od 6 do 20 sati, nedjeljom od 7 do 13.
Ovaj tjedan: kava za van i kroasan samo 2 €!
Imamo i integralni kruh bez šećera.
Dođite i probajte!', 'НОВА ПЕКАРНЯ У ВАШОМУ РАЙОНІ!
Щодня свіжий хліб, булочки й бурек.
Відчинено з 6 до 20 години, у неділю з 7 до 13.
Цього тижня: кава з собою і круасан лише 2 €!
У нас є й цільнозерновий хліб без цукру.
Приходьте й скуштуйте!', 'Текст «Нова пекарня». Правильна відповідь: «Кава з собою і круасан».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('59a10ec4-df3f-538d-8da8-cb3af1dd6cf9', v_aid, 9, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Bezolovni. Možete li provjeriti i tlak u gumama?', '["Šest eura neto, plaćen prijevoz.", "Mogu. Prednja lijeva guma je malo mekana.", "Super! Upoznala sam cijeli tim."]'::jsonb, 1, null, '{}'::text[], 'Bezolovni. Možete li provjeriti i tlak u gumama?', null, null, 'Діалог «На заправці»: «Bezolovni. Možete li provjeriti i tlak u gumama?» (Бензин. Можете перевірити ще й тиск у шинах?) — «Mogu. Prednja lijeva guma je malo mekana.» (Можу. Передня ліва шина трохи спущена.).', (select id from public.lessons where id = 'd6ca64d8-4c71-5936-a930-51e400f5681d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9cfc571b-4701-5aef-9dac-dc056d943a00', v_aid, 10, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ivana, kako mi stoji ova jakna?', '["Na oglasnoj ploči, pored kuhinje.", "Kroj je lijep, ali rukavi su ti predugi.", "Samo vani. U zgradi vrijedi zabrana pušenja."]'::jsonb, 1, null, '{}'::text[], 'Ivana, kako mi stoji ova jakna?', null, null, 'Діалог «У примірочній»: «Ivana, kako mi stoji ova jakna?» (Івано, як мені ця куртка?) — «Kroj je lijep, ali rukavi su ti predugi.» (Крій гарний, але рукави тобі задовгі.).', (select id from public.lessons where id = '7fb1b6e5-93b4-5776-b82b-25e7769fd32d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f017c52e-1d36-5871-975b-2bb06cbca766', v_aid, 11, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Oprostite, imate li šampon za suhu kosu?', '["Recite joj da sam bolestan i da danas ne dolazim.", "Dvadeset dva. Imam veliki kofer.", "Imamo. Ovaj je bez parfema, a ima i regenerator."]'::jsonb, 2, null, '{}'::text[], 'Oprostite, imate li šampon za suhu kosu?', null, null, 'Діалог «Для волосся й шкіри»: «Oprostite, imate li šampon za suhu kosu?» (Перепрошую, у вас є шампунь для сухого волосся?) — «Imamo. Ovaj je bez parfema, a ima i regenerator.» (Є. Цей без запаху, і до нього є бальзам.).', (select id from public.lessons where id = '9ba8e62a-83fd-5b08-9e01-760bc0f7219f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('594c2e21-22a7-5eb9-8359-315335cda47f', v_aid, 12, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koji je broj vašeg leta?', '["Možemo. Montiranje je besplatno.", "On je zidar, radi na gradilištu u Novom Zagrebu.", "Let iz Beča, slijetanje u deset sati."]'::jsonb, 2, null, '{}'::text[], 'Koji je broj vašeg leta?', null, null, 'Діалог «Де мій багаж?»: «Koji je broj vašeg leta?» (Який номер вашого рейсу?) — «Let iz Beča, slijetanje u deset sati.» (Рейс із Відня, приземлення о десятій.).', (select id from public.lessons where id = '69ec0776-4f69-5f86-afac-6652234a7da5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('59947a86-9101-5914-8551-64cb78e01fb6', v_aid, 13, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što ti jedeš ujutro?', '["Stanite ispred hotela i pričekajte me pet minuta.", "Obično zobene pahuljice s voćem i malo meda.", "Uglavnom da, ova stambena zgrada je mirna."]'::jsonb, 1, null, '{}'::text[], 'Što ti jedeš ujutro?', null, null, 'Діалог «Здоровий сніданок»: «Što ti jedeš ujutro?» (Що ти їси зранку?) — «Obično zobene pahuljice s voćem i malo meda.» (Зазвичай вівсянку з фруктами й трохи меду.).', (select id from public.lessons where id = 'bb7bc159-cb40-5a8a-91b7-c6da05c6342a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('384e4524-463f-5d4c-ac26-2dcb57e8d105', v_aid, 14, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Možemo li pomaknuti kavu na petak?', '["Kupaći kostim, kratke hlače i nekoliko tankih majica.", "Može, krajem tjedna sam slobodnija.", "Pošaljite životopis i kratko motivacijsko pismo."]'::jsonb, 1, null, '{}'::text[], 'Možemo li pomaknuti kavu na petak?', null, null, 'Діалог «Перенесемо?»: «Možemo li pomaknuti kavu na petak?» (Можемо перенести каву на п’ятницю?) — «Može, krajem tjedna sam slobodnija.» (Можна, наприкінці тижня я вільніша.).', (select id from public.lessons where id = '3365f423-e694-5b55-baa1-3205fba11aff'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4431f786-c3f3-5005-857c-2852d7a6b3e7', v_aid, 15, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoćete li se javiti na sastanak preko videopoziva?', '["Hoću, pošaljite mi link mailom.", "Svaki drugi dan, a vikendom trčim uz more.", "Oko tri i pol sata, sa stankom od petnaest minuta."]'::jsonb, 0, null, '{}'::text[], 'Hoćete li se javiti na sastanak preko videopoziva?', null, null, 'Діалог «Повідомлення секретарці»: «Hoćete li se javiti na sastanak preko videopoziva?» (Ви підключитеся до наради через відеодзвінок?) — «Hoću, pošaljite mi link mailom.» (Так, надішліть мені посилання імейлом.).', (select id from public.lessons where id = 'e806dd39-4d38-5781-ad2d-949961dd95f9'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e278ab5f-bcde-56b5-b7b9-e9a800cd68cc', v_aid, 16, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Oprostite, ima li u ovom kolaču oraha?', '["Тоді не можу, у мене алергія на арахіс.", "Є волоські горіхи й трохи арахісу.", "У нас є й паста без глютену, тільки скажіть."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Oprostite, ima li u ovom kolaču oraha?
Ivan: Ima oraha i malo kikirikija.
Daša: Onda ne mogu, alergična sam na kikiriki.
Ivan: Imamo voćnu salatu, ona je bez oraha.
Daša: Super. A je li tjestenina bez glutena?
Ivan: Imamo i tjesteninu bez glutena, samo recite.', 'Daša: Перепрошую, у цьому тістечку є горіхи?
Ivan: Є волоські горіхи й трохи арахісу.
Daša: Тоді не можу, у мене алергія на арахіс.
Ivan: У нас є фруктовий салат, він без горіхів.
Daša: Чудово. А паста без глютену?
Ivan: У нас є й паста без глютену, тільки скажіть.', 'Діалог «У ресторані з алергією»: «Oprostite, ima li u ovom kolaču oraha?» — «Ima oraha i malo kikirikija.», тобто «Є волоські горіхи й трохи арахісу.».', (select id from public.lessons where id = '6af82dd3-beb1-54cf-9c1b-44ec3cb12a35'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7b3fe512-1586-5cd0-8f5e-678b7be35d97', v_aid, 17, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imamo natječaj za skladištara. Ima li uvjeta koje ne ispunjavate?', '["У мене немає посвідчення на навантажувач.", "Центр може оплатити вам курси.", "Можете, тільки повідомте нам."]'::jsonb, 0, null, '{}'::text[], null, 'Marko: Dobar dan, tražim stalan posao.
Savjetnica: Imamo natječaj za skladištara. Ima li uvjeta koje ne ispunjavate?
Marko: Nemam vozačku za viličar.
Savjetnica: Zavod vam može platiti tečaj.
Marko: Super. A do tada? Trebam li honorarni posao?
Savjetnica: Možete, samo nam javite.', 'Marko: Добрий день, я шукаю постійну роботу.
Savjetnica: Є вакансія комірника. Є умови, яким ви не відповідаєте?
Marko: У мене немає посвідчення на навантажувач.
Savjetnica: Центр може оплатити вам курси.
Marko: Чудово. А до того? Мені шукати підробіток?
Savjetnica: Можете, тільки повідомте нам.', 'Діалог «У центрі зайнятості»: «Imamo natječaj za skladištara. Ima li uvjeta koje ne ispunjavate?» — «Nemam vozačku za viličar.», тобто «У мене немає посвідчення на навантажувач.».', (select id from public.lessons where id = 'c9b87882-5e31-5485-aea7-0169216466a8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('664d56e0-5a1b-58c0-9366-40634b01ba40', v_aid, 18, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Hoćeš li mi navečer pročitati bajku?', '["Погойдай мене на гойдалці, будь ласка!", "Так, але спершу ти купаєшся й дивишся один мультик.", "Ходімо, але зважай на менших дітей."]'::jsonb, 1, null, '{}'::text[], null, 'Filip: Mama, idemo na tobogan!
Darja: Idemo, ali pazi na mlađu djecu.
Filip: Zaljuljaj me na ljuljački, molim te!
Darja: Može. Nemoj se igrati u pijesku, nove su ti hlače.
Filip: Hoćeš li mi navečer pročitati bajku?
Darja: Hoću, ali prvo se kupaš i gledaš jedan crtić.', 'Filip: Мамо, ходімо на гірку!
Darja: Ходімо, але зважай на менших дітей.
Filip: Погойдай мене на гойдалці, будь ласка!
Darja: Добре. Не грайся в піску, в тебе нові штани.
Filip: А ввечері прочитаєш мені казку?
Darja: Так, але спершу ти купаєшся й дивишся один мультик.', 'Діалог «Гірка й гойдалка»: «Hoćeš li mi navečer pročitati bajku?» — «Hoću, ali prvo se kupaš i gledaš jedan crtić.», тобто «Так, але спершу ти купаєшся й дивишся один мультик.».', (select id from public.lessons where id = 'd43d6c65-1ce3-5c72-9ecd-cce2ed200fc2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('fcb3372c-56a5-56b3-94be-4527c1739a2a', v_aid, 19, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Moram li platiti dolazak?', '["Ми надішлемо техніка завтра до обіду.", "Ні, усе входить в абонплату.", "Вимкніть роутер на хвилину, а потім знову увімкніть."]'::jsonb, 1, null, '{}'::text[], null, 'Darja: Dobar dan, ja sam korisnik broj četiri sto dvadeset. Internet ne radi.
Operater: Isključite ruter na minutu pa ga ponovno uključite.
Darja: To radim svaki dan, ali i dalje nema signala.
Operater: Šaljemo tehničara sutra prije podne.
Darja: Moram li platiti dolazak?
Operater: Ne, sve je uključeno u pretplatu.', 'Darja: Добрий день, я абонент номер чотириста двадцять. Інтернет не працює.
Operater: Вимкніть роутер на хвилину, а потім знову увімкніть.
Darja: Я роблю це щодня, але сигналу досі немає.
Operater: Ми надішлемо техніка завтра до обіду.
Darja: Мені треба платити за виклик?
Operater: Ні, усе входить в абонплату.', 'Діалог «Інтернет не працює»: «Moram li platiti dolazak?» — «Ne, sve je uključeno u pretplatu.», тобто «Ні, усе входить в абонплату.».', (select id from public.lessons where id = 'b69a8cca-4918-562f-8ae5-22f8d7ba2f76'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e4b37497-3b07-5ab6-a058-8ad8013b2259', v_aid, 20, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Підтягни гвинт». Що ви скажете?', null, '["Zategni vijak.", "Tražim trosoban stan.", "Upali ventilator."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Підтягни гвинт.» — «Zategni vijak.».', (select id from public.lessons where id = 'dd2c0f3c-19f2-5c73-b448-a0631cd97e69'), 'PUBLISHED', 'claude_assessment_v5'),
  ('952ff23a-d1d1-5b98-93cc-eb2e6f0c6931', v_aid, 21, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Ці навушники не працюють». Що ви скажете?', null, '["Ove slušalice ne rade.", "Tražim poklon za mamu.", "Ove dvije marke su slične."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Ці навушники не працюють.» — «Ove slušalice ne rade.».', (select id from public.lessons where id = '6a7b0f42-510b-521e-9cc0-f77b2659d838'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4d1181b2-0d6d-5a9d-b832-61bd069d6368', v_aid, 22, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Можна залишити повідомлення?». Що ви скажете?', null, '["Prehlađen sam, danas ne dolazim.", "Je li ugovor na određeno?", "Mogu li ostaviti poruku?"]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Можна залишити повідомлення?» — «Mogu li ostaviti poruku?».', (select id from public.lessons where id = 'e806dd39-4d38-5781-ad2d-949961dd95f9'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2998df47-8d53-58a1-82af-866473f756b4', v_aid, 23, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «залізниця»', null, '[]'::jsonb, null, 'željeznica', '{}'::text[], null, null, null, '«залізниця» — željeznica.', (select id from public.lessons where id = 'cae7a47d-7fb4-5b03-a8cc-5a0df2ccd92f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f78b7451-2323-5a68-9af1-b39eaf986728', v_aid, 24, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «акваріум»', null, '[]'::jsonb, null, 'akvarij', '{}'::text[], null, null, null, '«акваріум» — akvarij.', (select id from public.lessons where id = '1968c7d5-4e3a-5b1e-92f6-88df711e9c54'), 'PUBLISHED', 'claude_assessment_v5'),
  ('32c4d939-10d2-5b76-8004-d62bf51cdc42', v_aid, 25, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «зламатися, зіпсуватися»', null, '[]'::jsonb, null, 'pokvariti se', '{}'::text[], null, null, null, '«зламатися, зіпсуватися» — pokvariti se.', (select id from public.lessons where id = '6a7b0f42-510b-521e-9cc0-f77b2659d838'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e043d536-7f2d-561c-9cf5-c60fbca9a01b', v_aid, 26, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ключі в маленькій шухляді.»', null, '["maloj", "Ključevi", "u", "ladici.", "su"]'::jsonb, null, 'Ključevi su u maloj ladici.', array['U maloj ladici su ključevi.']::text[], null, null, null, '«Ключі в маленькій шухляді.» — «Ključevi su u maloj ladici.».', (select id from public.lessons where id = 'de93d3ab-6769-5daf-9560-8858285a8136'), 'PUBLISHED', 'claude_assessment_v5'),
  ('fbba24de-9c03-5ea4-931f-2e4d564bd3ef', v_aid, 27, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я була в лікаря.»', null, '["sam", "liječnika.", "kod", "Bila"]'::jsonb, null, 'Bila sam kod liječnika.', array['Kod liječnika sam bila.']::text[], null, null, null, '«Я була в лікаря.» — «Bila sam kod liječnika.».', (select id from public.lessons where id = 'e806dd39-4d38-5781-ad2d-949961dd95f9'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2712507a-a980-54b8-99fe-43220bad4022', v_aid, 28, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Візьми непромокальні чоботи.»', null, '["nepromočive", "Uzmi", "čizme."]'::jsonb, null, 'Uzmi nepromočive čizme.', '{}'::text[], null, null, null, '«Візьми непромокальні чоботи.» — «Uzmi nepromočive čizme.».', (select id from public.lessons where id = 'c8297811-44ed-55a2-8cb5-d1bd9b8a6a73'), 'PUBLISHED', 'claude_assessment_v5'),
