-- Фінальна перевірка рівня A1 · 48 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a1-final' and cefr = 'A1';
  if v_aid is null then raise exception 'Немає тесту a1-final — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '0f0e3e0d-9081-573e-b794-8e3d5f608cee') then return; end if;  -- уже оновлено
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Кінець рівня (усі 13 модулів A1): 48 завдань на 4 навички. ~25 хв.', estimated_minutes = 25 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('0f0e3e0d-9081-573e-b794-8e3d5f608cee', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре, але капюшон я не вдягаю.", "На три сантиметри. І в поясі вони трохи завеликі.", "Чудово. Мені ще потрібен крем для чутливої шкіри."]'::jsonb, 0, null, '{}'::text[], 'Dobro, ali kapuljaču ne stavljam.', null, null, 'Прозвучало: «Dobro, ali kapuljaču ne stavljam.» — «Добре, але капюшон я не вдягаю.».', (select id from public.lessons where id = 'c8297811-44ed-55a2-8cb5-d1bd9b8a6a73'), 'PUBLISHED', 'claude_assessment_v5'),
  ('57dbdb39-17f4-5dde-87ef-3451c5e0d4a5', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре. Можете увімкнути кондиціонер?", "Іду в місто, на ринок. А ти?", "Звісно. Де мені зупинитися?"]'::jsonb, 0, null, '{}'::text[], 'Može. Možete li upaliti klimu?', null, null, 'Прозвучало: «Može. Možete li upaliti klimu?» — «Добре. Можете увімкнути кондиціонер?».', (select id from public.lessons where id = '458ee6ec-31d1-5758-adef-03612626088a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6665bdf4-1ef7-5922-b71f-d347db968ef5', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Де ви зустрічатимете Новий рік?", "Івано, яку хорватську книжку казок купити доньці?", "Іванно, як тут святкують Великдень?"]'::jsonb, 2, null, '{}'::text[], 'Ivana, kako se ovdje slavi Uskrs?', null, null, 'Прозвучало: «Ivana, kako se ovdje slavi Uskrs?» — «Іванно, як тут святкують Великдень?».', (select id from public.lessons where id = 'f67bd38c-a41c-51df-b9c0-081737600fce'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6096e5b1-33d9-53fe-af0b-f82e793b1684', v_aid, 4, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["У тебе вийде, ти дуже працьовита!", "Дякую, для мене це великий виклик.", "Розкажіть нам трохи про себе."]'::jsonb, 0, null, '{}'::text[], 'Uspjet ćeš, ti si jako vrijedna!', null, null, 'Прозвучало: «Uspjet ćeš, ti si jako vrijedna!» — «У тебе вийде, ти дуже працьовита!».', (select id from public.lessons where id = 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ae26c891-236a-54fe-b357-a54ff650536b', v_aid, 5, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["На полиці біля флешок.", "Тримай цю кнопку збоку, бабусю.", "Напиши «prebivalište» в пошуку на сайті."]'::jsonb, 0, null, '{}'::text[], 'Na polici pored USB ključića.', null, null, 'Прозвучало: «Na polici pored USB ključića.» — «На полиці біля флешок.».', (select id from public.lessons where id = '31bbedca-4b51-5478-8513-df5cb996ffd9'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e962ba19-01c0-5bc5-855e-ecb223d272d3', v_aid, 6, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дашо, коли в тебе обідня перерва?", "Дашо, що хочеш на сніданок?", "Є. І апельсиновий сік?"]'::jsonb, 2, null, '{}'::text[], 'Imamo. I sok od naranče?', null, null, 'Прозвучало: «Imamo. I sok od naranče?» — «Є. І апельсиновий сік?».', (select id from public.lessons where id = 'bb7bc159-cb40-5a8a-91b7-c6da05c6342a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('03086eb8-dc84-5077-99b8-24879a9140f7', v_aid, 7, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ні, це заборонено. Викличте вивіз великогабаритного сміття.", "Так, квартира в новобудові, на четвертому поверсі.", "Так, я Даша. Приємно познайомитися!"]'::jsonb, 1, null, '{}'::text[], 'Da, stan je u novogradnji, na četvrtom katu.', null, null, 'Прозвучало: «Da, stan je u novogradnji, na četvrtom katu.» — «Так, квартира в новобудові, на четвертому поверсі.».', (select id from public.lessons where id = '278947e3-ae50-5818-abd7-7f07b8ab5c44'), 'PUBLISHED', 'claude_assessment_v5'),
  ('dc377d03-8713-59e9-9015-4cbb0440ac98', v_aid, 8, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["На мою думку, трохи нудний.", "Моя донька займається волейболом. Тренер чудовий.", "Не хвилюйся, нам вистачить до кінця місяця."]'::jsonb, 2, null, '{}'::text[], 'Ne brini, imamo dovoljno do kraja mjeseca.', null, null, 'Прозвучало: «Ne brini, imamo dovoljno do kraja mjeseca.» — «Не хвилюйся, нам вистачить до кінця місяця.».', (select id from public.lessons where id = 'fac55dd6-0020-5997-8461-45ee2f94d3c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8cbd3cc5-d414-519a-b1fb-b83fed3c1125', v_aid, 9, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли треба скасувати бронювання?', 'Potvrda rezervacije', '["За день до того", "Не можна скасувати", "За годину"]'::jsonb, 0, null, '{}'::text[], null, 'Poštovana gospođo Kovalenko,
hvala na rezervaciji. Vaš stol za četiri osobe je u petak u 19 sati, na terasi.
Ako trebate dječju stolicu ili imate alergiju, javite nam.
Ako ne možete doći, molimo Vas da otkažete rezervaciju dan prije.
Srdačan pozdrav,
Restoran Lungomare', 'Шановна пані Коваленко,
дякуємо за бронювання. Ваш столик на чотирьох — у п’ятницю о 19 годині, на терасі.
Якщо вам потрібен дитячий стілець або у вас алергія, повідомте нам.
Якщо ви не можете прийти, просимо скасувати бронювання за день до того.
З повагою,
Ресторан «Lungomare»', 'Текст «Підтвердження бронювання». Правильна відповідь: «За день до того».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('6b891fbe-1461-53ce-a4b2-f460bb32b280', v_aid, 10, 'A1', 'reading', 'understand', 'multiple_choice', 'Скільки років виповнюється Івані?', 'Pozivnica za rođendan', '["Тридцять", "Двадцять", "Сорок"]'::jsonb, 0, null, '{}'::text[], null, 'Dragi prijatelji!
U subotu slavim trideseti rođendan i želim vas vidjeti. Zabava je u našem stanu od osam navečer. Imamo hranu i piće, vi donesite dobro raspoloženje! Ako dolazite, javite mi do četvrtka.
Vidimo se,
Ivana', 'Дорогі друзі!
У суботу я святкую тридцятий день народження і хочу вас побачити. Вечірка в нашій квартирі з восьмої вечора. У нас є їжа й напої, а ви принесіть гарний настрій! Якщо прийдете, дайте мені знати до четверга.
До зустрічі,
Івана', 'Текст «Запрошення на день народження». Правильна відповідь: «Тридцять».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('d50e0b88-6936-5b12-ba4f-50796e0e0d2c', v_aid, 11, 'A1', 'reading', 'understand', 'multiple_choice', 'Чому Олена пише записку?', 'Poruka na hladnjaku', '["Вона працює допізна", "Вона на морі", "Вона в лікарні"]'::jsonb, 0, null, '{}'::text[], null, 'Dragi Tarase,
danas radim do kasno. Molim te:
– izvadi rublje iz perilice i objesi ga na balkon;
– iznesi smeće;
– nahrani mačku.
Ručak je u hladnjaku, samo ga zagrij. Vidimo se navečer!
Olena', 'Дорогий Тарасе,
сьогодні я працюю допізна. Будь ласка:
– вийми білизну з пральної машини й повісь її на балкон;
– винеси сміття;
– погодуй кішку.
Обід у холодильнику, тільки розігрій його. Побачимося ввечері!
Олена', 'Текст «Записка на холодильнику». Правильна відповідь: «Вона працює допізна».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('66aea72c-cd82-5c20-a223-661cf9384170', v_aid, 12, 'A1', 'reading', 'understand', 'multiple_choice', 'Скільки днів діє новий пакет?', 'SMS od operatera', '["13 днів", "5 днів", "30 днів"]'::jsonb, 2, null, '{}'::text[], null, 'Poštovani,
Vaš paket podataka istječe sutra. Za novi paket pošaljite SMS s riječi DA na broj 1313. Novi paket košta 5 eura i vrijedi 30 dana. Ako imate pitanja, nazovite nas.
Vaš operater', 'Шановний клієнте,
ваш пакет інтернету закінчується завтра. Щоб отримати новий пакет, надішліть SMS зі словом DA на номер 1313. Новий пакет коштує 5 євро й діє 30 днів. Якщо маєте запитання, зателефонуйте нам.
Ваш оператор', 'Текст «SMS від оператора». Правильна відповідь: «30 днів».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('296fe39e-36bd-53ac-a0ef-fe1e7316bb0b', v_aid, 13, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли заняття?', 'Prijavnica za tečaj', '["У суботу", "У понеділок і середу", "У вівторок і четвер"]'::jsonb, 2, null, '{}'::text[], null, 'PRIJAVNICA ZA TEČAJ HRVATSKOGA JEZIKA
Ime i prezime: Olena Kovalenko
Datum rođenja: 12. 3. 1990.
Državljanstvo: ukrajinsko
Adresa: Ilica 25, Zagreb
Broj mobitela: 091 765 4321
Razina: A1
Termin: utorak i četvrtak, 18 – 20 sati
Potpis: Olena Kovalenko', 'АНКЕТА НА КУРС ХОРВАТСЬКОЇ МОВИ
Ім’я та прізвище: Олена Коваленко
Дата народження: 12.03.1990
Громадянство: українське
Адреса: Іліца, 25, Загреб
Номер мобільного: 091 765 4321
Рівень: A1
Час занять: вівторок і четвер, 18 – 20 година
Підпис: Олена Коваленко', 'Текст «Анкета на курс». Правильна відповідь: «У вівторок і четвер».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('b08373a0-c042-559b-800e-04db2467bca1', v_aid, 14, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Gdje si se presvukao?', '["U svlačionici, svatko ima svoj ormarić.", "Prije Uskrsa je korizma, a tjedan prije je Cvjetnica.", "Morate, i papuče. Djeca se često zaprljaju."]'::jsonb, 0, null, '{}'::text[], 'Gdje si se presvukao?', null, null, 'Діалог «На складі»: «Gdje si se presvukao?» (Де ти перевдягнувся?) — «U svlačionici, svatko ima svoj ormarić.» (У роздягальні, у кожного своя шафка.).', (select id from public.lessons where id = '2c56a486-dbbb-5102-b7cb-754c59cf94c3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('1a78fcb8-72a2-5453-94da-cd304888955a', v_aid, 15, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kako biste se opisali?', '["Pouzdana sam i samostalna, a kolege kažu da sam strpljiva.", "Ljeti je puno gostiju, ali kolege su super.", "Toplomjer je pokazao trideset osam i pol."]'::jsonb, 0, null, '{}'::text[], 'Kako biste se opisali?', null, null, 'Діалог «Розкажіть про себе»: «Kako biste se opisali?» (Як би ви себе описали?) — «Pouzdana sam i samostalna, a kolege kažu da sam strpljiva.» (Я надійна й самостійна, а колеги кажуть, що я терпляча.).', (select id from public.lessons where id = 'fc1baff0-0e48-5676-bd3c-47d88d31e582'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5ed159f5-45b8-56b0-9eff-ecfbd5dabe56', v_aid, 16, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ima li izvora pitke vode?', '["Vukovarska dvadeset, treći kat.", "Ima, ali ponesi i svoju vodu.", "Poništač je kod vrata, žuti aparat."]'::jsonb, 1, null, '{}'::text[], 'Ima li izvora pitke vode?', null, null, 'Діалог «Печера й каньйон»: «Ima li izvora pitke vode?» (Там є джерела питної води?) — «Ima, ali ponesi i svoju vodu.» (Є, але візьми й свою воду.).', (select id from public.lessons where id = '84a20a00-701a-5ce5-a3c8-fca72986f912'), 'PUBLISHED', 'claude_assessment_v5'),
  ('14362d1d-7d16-5710-ac37-01154b2675c7', v_aid, 17, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dašo, znaš li da je kravata hrvatski izum?', '["Stvarno? Mislila sam da je iz Francuske.", "U ormaru, pored vunenih rukavica.", "Moj dečko me pitao na plaži, za zalazak sunca."]'::jsonb, 0, null, '{}'::text[], 'Dašo, znaš li da je kravata hrvatski izum?', null, null, 'Діалог «Звідки краватка?»: «Dašo, znaš li da je kravata hrvatski izum?» (Дашо, знаєш, що краватка — хорватський винахід?) — «Stvarno? Mislila sam da je iz Francuske.» (Справді? Я думала, що вона з Франції.).', (select id from public.lessons where id = '5ae02c5f-7ba1-5b59-be71-f744d6e9b169'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5adc00c9-76ec-51d1-bbad-ed730c238167', v_aid, 18, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan! Vi ste novi stanari na trećem katu?', '["Prvo na određeno, s probnim radom od tri mjeseca.", "Da, ja sam Daša. Drago mi je!", "Na trgu, bit će koncert i vatromet u ponoć."]'::jsonb, 1, null, '{}'::text[], 'Dobar dan! Vi ste novi stanari na trećem katu?', null, null, 'Діалог «Знайомство на сходах»: «Dobar dan! Vi ste novi stanari na trećem katu?» (Добрий день! Ви нові мешканці на третьому поверсі?) — «Da, ja sam Daša. Drago mi je!» (Так, я Даша. Приємно познайомитися!).', (select id from public.lessons where id = 'a42b9121-2ec0-5064-909b-f59f315b3c4a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b5cc06ee-e36d-5bce-a586-863e0b84b4fc', v_aid, 19, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koji zub vas boli?', '["Još ne, upravo se oblačim.", "Dolje lijevo, kad pijem hladno.", "Jako. Ponekad imam nostalgiju, sjećam se mame i našeg vrta."]'::jsonb, 1, null, '{}'::text[], 'Koji zub vas boli?', null, null, 'Діалог «Болить зуб»: «Koji zub vas boli?» (Який зуб вас болить?) — «Dolje lijevo, kad pijem hladno.» (Знизу ліворуч, коли п’ю холодне.).', (select id from public.lessons where id = '247c3445-6ba3-50f0-a441-9073d6734451'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e5a733e3-a4f1-59f5-8ec4-ab5c23d2230c', v_aid, 20, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Bako, kako se radi tvoj kolač s jabukama?', '["Po mom mišljenju, malo je dosadan.", "Prvo oguli jabuke i nasjeckaj ih.", "Brzi vlak polazi u osam i petnaest."]'::jsonb, 1, null, '{}'::text[], 'Bako, kako se radi tvoj kolač s jabukama?', null, null, 'Діалог «Бабусин рецепт»: «Bako, kako se radi tvoj kolač s jabukama?» (Бабусю, як робиться твій пиріг з яблуками?) — «Prvo oguli jabuke i nasjeckaj ih.» (Спочатку почисть яблука й поріж їх.).', (select id from public.lessons where id = '3e652232-866b-5edf-ac05-d61ee7a325fe'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d0d6abe8-7cad-5f8b-a402-e2b7cbf4585d', v_aid, 21, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imate li mast za modrice?', '["Muškarci se rukuju, a prijatelji se ljube dvaput u obraz.", "Imamo. Mažite tri puta dnevno.", "Malo. Mentor je rekao da je sigurnost najvažnija."]'::jsonb, 1, null, '{}'::text[], 'Imate li mast za modrice?', null, null, 'Діалог «Як приймати?»: «Imate li mast za modrice?» (У вас є мазь від синців?) — «Imamo. Mažite tri puta dnevno.» (Є. Мажте тричі на день.).', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7fadfe5f-8376-51ad-ae78-55400bbc6161', v_aid, 22, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobro. Trebate li još nešto?', '["Drugi, i baterija mu traje duže.", "Volontirala sam u udruzi, a ondje je divna zajednica.", "Na košulji nedostaje jedan gumb na ovratniku."]'::jsonb, 2, null, '{}'::text[], 'Dobro. Trebate li još nešto?', null, null, 'Діалог «У кравчині»: «Dobro. Trebate li još nešto?» (Добре. Ще щось потрібно?) — «Na košulji nedostaje jedan gumb na ovratniku.» (На сорочці бракує одного ґудзика на комірі.).', (select id from public.lessons where id = '7fb1b6e5-93b4-5776-b82b-25e7769fd32d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('841a26d3-6d2d-5175-b2b1-8109826f06cd', v_aid, 23, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Smijemo li sušiti rublje na tavanu?', '["Ovjeru možeš napraviti kod javnog bilježnika, blizu je.", "Na automatu ili SMS-om. Parkirnu kartu stavite iza stakla.", "Smijete, tavan je zajednički prostor."]'::jsonb, 2, null, '{}'::text[], 'Smijemo li sušiti rublje na tavanu?', null, null, 'Діалог «Розмова з управителем»: «Smijemo li sušiti rublje na tavanu?» (Можна сушити білизну на горищі?) — «Smijete, tavan je zajednički prostor.» (Можна, горище — місце загального користування.).', (select id from public.lessons where id = 'f296bc84-8059-5981-a5b9-9d4531627e18'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ba479330-cd0f-5789-b5f2-93914dcf97b5', v_aid, 24, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Spavaju li djeca poslije ručka?', '["Tražimo. Radno mjesto je na nepuno radno vrijeme.", "Nudimo, doručak i večera su uključeni.", "Da, popodnevni odmor je od jedan do tri."]'::jsonb, 2, null, '{}'::text[], 'Spavaju li djeca poslije ručka?', null, null, 'Діалог «Перший тиждень»: «Spavaju li djeca poslije ručka?» (Діти сплять після обіду?) — «Da, popodnevni odmor je od jedan do tri.» (Так, денний сон — з першої до третьої.).', (select id from public.lessons where id = '42c31cfb-8680-5450-8453-245f3abd475a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e8abf1e4-da48-50b0-a0b9-a8b02f61fef7', v_aid, 25, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Mogu li dobiti novac natrag?', '["Можна, але для цього йдіть у службу підтримки клієнтів.", "Не треба, видно, що він пошкоджений.", "На цьому светрі пляма й маленька дірка на рукаві."]'::jsonb, 0, null, '{}'::text[], null, 'Darja: Ovaj džemper ima mrlju i malu rupu na rukavu.
Prodavačica: Žao mi je. Je li etiketa još na njemu?
Darja: Jest. Moram li reći razlog povrata?
Prodavačica: Ne morate, vidi se da je oštećen.
Darja: Mogu li dobiti novac natrag?
Prodavačica: Možete, ali za to idite u službu za korisnike.', 'Darja: На цьому светрі пляма й маленька дірка на рукаві.
Prodavačica: Мені шкода. Етикетка ще на ньому?
Darja: Так. Мені треба пояснювати причину повернення?
Prodavačica: Не треба, видно, що він пошкоджений.
Darja: Можна отримати гроші назад?
Prodavačica: Можна, але для цього йдіть у службу підтримки клієнтів.', 'Діалог «Пляма на светрі»: «Mogu li dobiti novac natrag?» — «Možete, ali za to idite u službu za korisnike.», тобто «Можна, але для цього йдіть у службу підтримки клієнтів.».', (select id from public.lessons where id = '6a7b0f42-510b-521e-9cc0-f77b2659d838'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c113e624-0e85-5e13-8a1a-22403b6c36ff', v_aid, 26, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jesam, evo ga sad. Kako da resetiram lozinku?', '["Я ввела ім’я користувача, але не отримала код підтвердження.", "Луко, я забула пароль від банку!", "Введи код і зміни пароль. Зроби надійний!"]'::jsonb, 2, null, '{}'::text[], null, 'Daša: Luka, zaboravila sam lozinku za banku!
Luka: Klikni na «Zaboravili ste lozinku?».
Daša: Unijela sam korisničko ime, ali nisam dobila kod za potvrdu.
Luka: Jesi li provjerila poruke na mobitelu?
Daša: Jesam, evo ga sad. Kako da resetiram lozinku?
Luka: Unesi kod i promijeni lozinku. Napravi jaku!', 'Daša: Луко, я забула пароль від банку!
Luka: Натисни «Забули пароль?».
Daša: Я ввела ім’я користувача, але не отримала код підтвердження.
Luka: Ти перевірила повідомлення на телефоні?
Daša: Так, ось він прийшов. Як мені скинути пароль?
Luka: Введи код і зміни пароль. Зроби надійний!', 'Діалог «Я забула пароль»: «Jesam, evo ga sad. Kako da resetiram lozinku?» — «Unesi kod i promijeni lozinku. Napravi jaku!», тобто «Введи код і зміни пароль. Зроби надійний!».', (select id from public.lessons where id = 'f355be7d-c423-5651-938e-71b8ca970a62'), 'PUBLISHED', 'claude_assessment_v5'),
  ('58da65b8-75e1-5e7f-83b2-02a2faae4b90', v_aid, 27, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Darja, jesi li ikad bila na Hvaru?', '["Колись поїду, коли матиму час.", "Ні, я ніколи не була на островах.", "Якось організуюся."]'::jsonb, 1, null, '{}'::text[], null, 'Marko: Darja, jesi li ikad bila na Hvaru?
Darja: Nisam, nikad nisam bila na otocima.
Marko: Svatko mora jednom vidjeti Hvar!
Darja: Nekad ću otići, kad budem imala vremena.
Marko: Možeš ići bilo kad, trajekt vozi svaki dan.
Darja: Nekako ću se organizirati.', 'Marko: Даріє, ти коли-небудь була на Хварі?
Darja: Ні, я ніколи не була на островах.
Marko: Кожен має хоч раз побачити Хвар!
Darja: Колись поїду, коли матиму час.
Marko: Можеш поїхати будь-коли, пором ходить щодня.
Darja: Якось організуюся.', 'Діалог «Ти коли-небудь…?»: «Darja, jesi li ikad bila na Hvaru?» — «Nisam, nikad nisam bila na otocima.», тобто «Ні, я ніколи не була на островах.».', (select id from public.lessons where id = '3f440ad8-f057-5898-b773-6aa8816fa8a3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('cb05028d-3c03-59fb-85b5-33e76a138c5f', v_aid, 28, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Mogu li ponijeti loptu u vrtić?', '["Я ще одягаюся, мамо.", "Філіпе, ти готовий? Через десять хвилин вирушаємо.", "Можна. І візьми шапку, надворі холодно!"]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Filipe, jesi li spreman? Za deset minuta krećemo.
Filip: Još se oblačim, mama.
Darja: Počešljaj se i obuj se, čekam te na vratima.
Filip: Mogu li ponijeti loptu u vrtić?
Darja: Možeš. I ponesi kapu, vani je hladno!
Filip: Dobro! Mama, ti se danas ne šminkaš?', 'Darja: Філіпе, ти готовий? Через десять хвилин вирушаємо.
Filip: Я ще одягаюся, мамо.
Darja: Причешися і взуйся, я чекаю тебе біля дверей.
Filip: Можна мені взяти м’яч у садок?
Darja: Можна. І візьми шапку, надворі холодно!
Filip: Добре! Мамо, ти сьогодні не фарбуєшся?', 'Діалог «Збираємо дитину»: «Mogu li ponijeti loptu u vrtić?» — «Možeš. I ponesi kapu, vani je hladno!», тобто «Можна. І візьми шапку, надворі холодно!».', (select id from public.lessons where id = '54f17cf7-3c17-5978-b400-b6b6888c9f84'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bb54d918-4bff-54b6-b80a-8673231144f4', v_aid, 29, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Idem u grad, na tržnicu. A ti?', '["Так, у центрі. Можу підвезти тебе машиною.", "Чудово! Дорогою можу заскочити в пекарню.", "А я сьогодні на роботі до п’ятої."]'::jsonb, 2, null, '{}'::text[], null, 'Luka: Dašo, kamo ideš tako rano?
Daša: Idem u grad, na tržnicu. A ti?
Luka: Ja sam danas na poslu do pet.
Daša: Gdje je tvoj ured, u centru?
Luka: Da, u centru. Mogu te odvesti autom.
Daša: Super! Usput mogu svratiti u pekaru.', 'Luka: Дашо, куди ти так рано?
Daša: Іду в місто, на ринок. А ти?
Luka: А я сьогодні на роботі до п’ятої.
Daša: Де твій офіс, у центрі?
Luka: Так, у центрі. Можу підвезти тебе машиною.
Daša: Чудово! Дорогою можу заскочити в пекарню.', 'Діалог «Куди ти йдеш?»: «Idem u grad, na tržnicu. A ti?» — «Ja sam danas na poslu do pet.», тобто «А я сьогодні на роботі до п’ятої.».', (select id from public.lessons where id = '12012395-7359-503b-89c9-ee1807f89d6b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d41f7407-0b6d-51f5-b934-52ccbb9280e2', v_aid, 30, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Izvolite. Trebate li i omote za knjige?', '["Для малювання потрібні ще акварель, темпера й кольоровий папір.", "Так, десять обкладинок. І кольорові олівці, фломастери й ножиці.", "Добрий день, мені потрібні робочі зошити для другого класу."]'::jsonb, 1, null, '{}'::text[], null, 'Darja: Dobar dan, trebam radne bilježnice za drugi razred.
Prodavačica: Izvolite. Trebate li i omote za knjige?
Darja: Da, deset omota. I bojice, flomastere i škare.
Prodavačica: Za likovni trebate i vodene boje, tempere i kolaž papir.
Darja: Joj, puno toga! Koliko je sve ukupno?
Prodavačica: Pedeset dva eura. Želite li vrećicu?', 'Darja: Добрий день, мені потрібні робочі зошити для другого класу.
Prodavačica: Прошу. Вам потрібні й обкладинки для книжок?
Darja: Так, десять обкладинок. І кольорові олівці, фломастери й ножиці.
Prodavačica: Для малювання потрібні ще акварель, темпера й кольоровий папір.
Darja: Ой, як багато! Скільки все разом?
Prodavačica: П’ятдесят два євро. Бажаєте пакет?', 'Діалог «У книгарні»: «Izvolite. Trebate li i omote za knjige?» — «Da, deset omota. I bojice, flomastere i škare.», тобто «Так, десять обкладинок. І кольорові олівці, фломастери й ножиці.».', (select id from public.lessons where id = 'e4904007-82bc-5759-89a9-05fb7a2c65c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5d98db8c-b000-56f8-80b3-df5d81fdb57e', v_aid, 31, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я складу план подорожі». Що ви скажете?', null, '["Gledaj, dupini!", "Napravit ću plan puta.", "Idemo na Plitvice."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Я складу план подорожі.» — «Napravit ću plan puta.».', (select id from public.lessons where id = '373074e1-3c4b-5d0f-a4f3-3ed06e0904f2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e782aa8e-b60d-59aa-91c0-ee7563e29ee8', v_aid, 32, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Їдь обережно!». Що ви скажете?', null, '["Ne mogu naći svoju prtljagu.", "Vozi pažljivo!", "Kada će auto biti gotov?"]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Їдь обережно!» — «Vozi pažljivo!».', (select id from public.lessons where id = '0b04119b-4d38-5d99-8237-caa95fdcfd95'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a8b26e04-4c40-54b6-8f27-b5b139411538', v_aid, 33, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Щасливого Нового року!». Що ви скажете?', null, '["Šetala sam starim gradom.", "Sretna Nova godina!", "Samo se šalim!"]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Щасливого Нового року!» — «Sretna Nova godina!».', (select id from public.lessons where id = '33c041a0-e71a-55c1-94c8-64941876c6d2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('49def0cf-6eb7-5024-80e3-054f9a6238b1', v_aid, 34, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Надішліть резюме, будь ласка». Що ви скажете?', null, '["Gdje da potpišem ugovor?", "Ovdje se ne smije pušiti.", "Pošaljite životopis, molim."]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Надішліть резюме, будь ласка.» — «Pošaljite životopis, molim.».', (select id from public.lessons where id = 'c9b87882-5e31-5485-aea7-0169216466a8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9e18c73e-34d5-53b5-a2f0-8a836933ad60', v_aid, 35, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я люблю природу». Що ви скажете?', null, '["Šetali smo šetnicom.", "Volim prirodu.", "Curi mi nos."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Я люблю природу.» — «Volim prirodu.».', (select id from public.lessons where id = '84a20a00-701a-5ce5-a3c8-fca72986f912'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e5204521-12c8-504b-80a7-20a1b93264f0', v_aid, 36, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «присяжний перекладач»', null, '[]'::jsonb, null, 'sudski tumač', '{}'::text[], null, null, null, '«присяжний перекладач» — sudski tumač.', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d14efd7d-032e-5488-8290-c2d9641b976b', v_aid, 37, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «роботодавець»', null, '[]'::jsonb, null, 'poslodavac', '{}'::text[], null, null, null, '«роботодавець» — poslodavac.', (select id from public.lessons where id = 'c9b87882-5e31-5485-aea7-0169216466a8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f6cf4762-b919-58ec-ba85-86872cf68556', v_aid, 38, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «кіоск»', null, '[]'::jsonb, null, 'kiosk', '{}'::text[], null, null, null, '«кіоск» — kiosk.', (select id from public.lessons where id = '3ea9520d-2baa-56b2-aa85-402e3e3ecb9b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6e6c1c12-3de4-55d5-bceb-9582137ef8aa', v_aid, 39, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «навіть»', null, '[]'::jsonb, null, 'čak', '{}'::text[], null, null, null, '«навіть» — čak.', (select id from public.lessons where id = 'ad0bc1f4-2808-5b24-969d-9da64d4a7a4d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('3fb49d7d-6d67-5f78-810e-5f0c4b995b06', v_aid, 40, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «приморський»', null, '[]'::jsonb, null, 'primorski', '{}'::text[], null, null, null, '«приморський» — primorski.', (select id from public.lessons where id = '8633c234-d638-57f1-ad92-1c78be43fb07'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a587669f-a848-59ef-9f92-805e1dfb22b3', v_aid, 41, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Можете це загорнути?»', null, '["Možete", "zamotati?", "to", "li"]'::jsonb, null, 'Možete li to zamotati?', '{}'::text[], null, null, null, '«Можете це загорнути?» — «Možete li to zamotati?».', (select id from public.lessons where id = '86d268a5-7193-53c5-955b-cf6cc69116f1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a08c3f9f-51ef-564a-92a5-ff615c413ab6', v_aid, 42, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ти переслав йому файл?»', null, '["datoteku?", "mu", "Jesi", "proslijedio", "li"]'::jsonb, null, 'Jesi li mu proslijedio datoteku?', '{}'::text[], null, null, null, '«Ти переслав йому файл?» — «Jesi li mu proslijedio datoteku?».', (select id from public.lessons where id = '71537166-9f48-503f-b564-3a4f99a192c5'), 'PUBLISHED', 'claude_assessment_v5'),
